DRY_RUN = False
# ---- 审计修复I2: 滑点显式建模 ----
# 下单限价相对最新价附加滑点: 买入价=最新价x(1+SLIPPAGE_PCT)上移, 卖出价下移,
# 使费用/净利闸门与手数估算更贴近真实可成交价; 聚宽回测兼容层按同值模拟成交价。
SLIPPAGE_PCT = 0.002
# 第六轮零预设审计修复(2026-10-04): 滑点按价格差异化 —— 固定 0.2% 滑点对低价股(5元以下)
# 占比过高(每元波动仅0.2%, 滑点相当于1个价差), 对高价股占比偏低。现按价格分段:
#   * 低价股(<10元): 提高滑点到 0.3% (真实盘口价差更大)
#   * 中价股(10-50元): 保持 0.2%
#   * 高价股(>50元): 降低滑点到 0.15% (盘口价差相对更小)
def _slippage_for(price):
    """按价格返回本笔滑点比例(第六轮零预设审计修复 2026-10-04)。"""
    try:
        _px = float(price or 0)
        if _px <= 0:
            return SLIPPAGE_PCT
        if _px < 10.0:
            return 0.003    # 低价股: 盘口价差相对更大
        if _px > 50.0:
            return 0.0015   # 高价股: 盘口价差相对更小
        return SLIPPAGE_PCT  # 中价股: 保持默认
    except Exception:
        return SLIPPAGE_PCT
