_SENTIMENT_READY = False                 # 数据已就绪且信号有效; 初始False, 取数成功才置True

# ---- 情绪常量(全部 SENT_ 前缀, 不进入宿主 param_fingerprint) ----
SENT_VERSION = '0.1.0'
SENT_LAG_DAYS = 1                        # 日频情绪滞后交易日数(铁律勿改)
SENT_ZSCORE_WIN = 60                     # 滚动z-score窗口(交易日)
SENT_MIN_PERIODS = 20                    # 滚动统计最小样本数
SENT_WINSORIZE_LOWER = 0.01              # 缩尾下分位
SENT_WINSORIZE_UPPER = 0.99              # 缩尾上分位
SENT_CLIP_LIMIT = 3.0                    # z-score截断限
SENT_EWMA_SPAN = 5                       # EWMA平滑跨度(交易日)
