def sent_bootstrap():
    # 启动初始化: 初始化状态字典并打版本/指纹日志; V2.6.61 R2起不在此处拉数据(详见下方说明)
    global _SENTIMENT_READY
    if not _SENTIMENT_ON:
        return
    try:
        SENT_STATE.clear()
        SENT_STATE['ready'] = False
        SENT_STATE['gate_skip'] = False
        SENT_STATE['size_mult'] = 1.0
        SENT_STATE['overrides'] = {}
        SENT_STATE['rows'] = []
        _SENTIMENT_READY = False
        _sent_wlog('初始化: VERSION=%s Phase=%d 指纹=%s (数据未就绪时全部中性)'
                   % (SENT_VERSION, _SENTIMENT_PHASE, sent_fingerprint()))
        if _SENTIMENT_PHASE >= 3:
            _sent_wlog('L2增强说明: 宿主为规则型买入(缩量低吸), 无独立技术评分通道, '
                       'L2增强保留参数与指纹但不改变买入结果; L1/L3/L4 全量生效')
        # V2.6.61 R2修复(2026-10-17用户确认方案A): 启动绝不在init中同步拉取情绪数据 ——
        #   旧版此处直接调sent_daily_refresh()→sent_fetch_all_data()同步拉取
        #   SENT_BACKFILL_DAYS自然日x全市场5227只日线(客户端22:00实测init被堵死在此步),
        #   宿主初始化全部推迟: 启动横幅后半段/资金风控口径/账号探测/对账/定时器注册
        #   迟迟不执行, 策略长时间处于"半就绪"状态。
        #   情绪信号为日频滞后1日数据, 晚数分钟就绪无任何损失; 首次刷新延后至
        #   timer_poll首轮(挂载点已就位: 幂等+SENT_RETRY_SEC节流+失败降级中性),
        #   就绪前买入侧全部中性(gate_skip=False/size_mult=1.0), 不影响交易决策。
        _sent_wlog('启动初始化完成(仅置状态未拉数据): 首次情绪刷新延后至定时器首轮, '
                   '宿主初始化不被阻塞')
    except Exception as _e:
        _SENTIMENT_READY = False
        _sent_wlog('情绪初始化异常(继续中性): %s' % _e)


def sent_daily_refresh():
    # 每交易日刷新情绪信号(滞后1日); V2.6.76: 取数已移交后台线程(见 sent_fetch_all_data),
    #   主线程此处只做幂等节流判定并"发一条刷新指令", 立即返回, 绝不阻塞盘中轮询。
    #   幂等: 今日已成功刷新过则不再发起; 失败则按 SENT_RETRY_SEC 节流重试。
    if not _SENTIMENT_ON:
        return
    try:
        _t = _sent_today()
        if SENT_STATE.get('last_fetch_date') == _t:
            return                      # 今日已刷新
        _now = time.time()
        if (_now - (SENT_STATE.get('last_try_ts') or 0.0)) < SENT_RETRY_SEC:
            return                      # 重试节流
        SENT_STATE['last_try_ts'] = _now
        # 发起后台取数(立即返回None, 不阻塞); 幂等由 sent_fetch_all_data 内的非阻塞锁保证
        sent_fetch_all_data()
    except Exception as _e:
        # V2.6.78 P2-1: 异常节流 — 每60秒最多一条, 持续故障持续有信号但不刷屏
        import time as _t
        _now_ts = _t.time()
        _last_err_ts = SENT_STATE.get("last_err_ts", 0.0)
        if _now_ts - _last_err_ts >= 60.0:
            SENT_STATE["last_err_ts"] = _now_ts
            _sent_wlog('情绪刷新调度异常(保持中性): %s' % _e)


def _sent_reset_ready(why):
    # 降级中性: 清空信号并复位就绪标记
    global _SENTIMENT_READY
    _SENTIMENT_READY = False
    SENT_STATE['ready'] = False
    SENT_STATE['err'] = why
    SENT_STATE['gate_skip'] = False
    SENT_STATE['size_mult'] = 1.0
    SENT_STATE['overrides'] = {}
    _sent_wlog('情绪降级中性: %s' % why)


def sent_gate_skip():
    # L1闸门: 恐慌/狂热/极端事件跳过新开仓(未就绪=False, 不阻塞)
    if not (_SENTIMENT_ON and _SENTIMENT_READY):
        return False
    return bool(SENT_STATE.get('gate_skip', False))


def sent_size_mult():
    # L4仓位乘数: 过热收缩, 下限保护; 未就绪=1.0
    if not (_SENTIMENT_ON and _SENTIMENT_READY):
        return 1.0
    m = SENT_STATE.get('size_mult')
    if isinstance(m, (int, float)) and m > 0:
        return float(m)
    return 1.0


def sent_param_overrides():
    # L3 Regime参数覆写字典(键=宿主常量名); 未就绪={}
    if not (_SENTIMENT_ON and _SENTIMENT_READY):
        return {}
    o = SENT_STATE.get('overrides')
    if isinstance(o, dict):
        return dict(o)
    return {}


def sent_param(name, default):
    # 读取宿主参数(带L3覆写); 未覆写返回 default
    o = sent_param_overrides()
    if name in o:
        return o[name]
    return default


